-- GenDB engine variant Q14-always_true_conjunct: template q14.sql, kind always_true_conjunct (generated by generate.py; frozen)
SELECT
  100.00 * SUM(
    CASE
      WHEN p_type LIKE 'PROMO%'
      THEN l_extendedprice * (
        1 - l_discount
      )
      ELSE 0
    END
  ) / SUM(l_extendedprice * (
    1 - l_discount
  )) AS promo_revenue
FROM lineitem, part
WHERE
  l_partkey = p_partkey
  AND l_shipdate >= $1
  AND l_shipdate < $1 + INTERVAL '1 MONTH'
  AND l_orderkey = l_orderkey
